import { PlaneGeometry, Mesh, MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import { createText } from '@/text';
import { } from '@/primitives';

export default function createNode(config, ctx) {
  const { Group } = ctx.THREE;

  // Root container
  const root = new Group();

  // ---------- Plane ----------
  const planeWidth = 1.6;   // approximate aspect of the image (512 / 320)
  const planeHeight = 1.0;
  const geometry = new PlaneGeometry(planeWidth, planeHeight);
  const material = new MeshBasicNodeMaterial();

  // Load texture asynchronously; the function remains synchronous
  if (config.imageUrl) {
    ctx.textureLoader
      .loadTexture(config.imageUrl)
      .then((tex) => {
        material.map = tex;
        material.needsUpdate = true;
      })
      .catch(() => {
        // texture failed, keep material plain
      });
  }

  const planeMesh = new Mesh(geometry, material);
  root.add(planeMesh);

  // ---------- Text ----------
  const textItems =
    config.textContent ??
    config.intent?.visualSpec?.textContent ??
    [];

  for (const item of textItems) {
    const txt = ctx.fontAtlas.createText(item.text ?? String(item), {
      fontSize: item.typography?.fontSize ?? 96,
      color: (config.colors && config.colors.paper) || '#e8ecf2',
      align: 'center',
    });

    // Position text slightly in front of the plane to avoid Z‑fighting
    txt.position.set(0, 0, 0.01);
    root.add(txt);
  }

  // ---------- Cleanup ----------
  const timelines = []; // store any GSAP timelines if they are added later

  function cleanup() {
    // Dispose material & texture
    if (material.map) material.map.dispose();
    material.dispose();

    // Dispose geometry
    geometry.dispose();

    // Kill any GSAP timelines
    timelines.forEach((t) => t.kill());

    // Remove children
    root.traverse((obj) => {
      if (obj.isMesh && obj !== planeMesh) {
        if (obj.geometry) obj.geometry.dispose();
        if (obj.material) {
          if (Array.isArray(obj.material)) {
            obj.material.forEach((m) => m.dispose());
          } else {
            obj.material.dispose();
          }
        }
      }
    });
  }

  // Attach userData
  root.userData.handlers = {}; // no interactive handlers required
  root.userData.cleanup = cleanup;

  // Return the assembled object
  return root;
}
